def main():
    rows = json.loads((ROOT / "validation/research/run-2026-09-08-02/external-rows.json").read_text(encoding="utf-8"))
    rows = [r for r in rows if r["source_file"] == "партия-01.md"]
    notes = {}
    for line in NOTES.strip().splitlines():
        number, kind, note = line.split("|", 2)
        assert int(number) not in notes
        notes[int(number)] = (kind, note)
    assert set(notes) == {r["source_line"] for r in rows}, "Every original row needs its own review"
    sources = {78: ["S20"], 79: ["S20"], 130: ["S23"], 132: ["S19", "S23"],
               136: ["S22"], 137: ["S21"]}
    for row in rows:
        kind, note = notes[row["source_line"]]
        row["research_review_2026_09_09"] = {
            "semantic_review": "completed_individually", "semantic_class": kind, "assessment": note,
            "primary_source_ids": sources.get(row["source_line"], []),
            "primary_evidence_scope": "partial_mechanism_only" if row["source_line"] in sources else "not_verified",
            "game_build_attribution": "not_fully_verified", "numeric_calibration_eligible": False,
            "numeric_exclusion_reason": "No matched scene/build/settings/hardware measurement with base FPS and independent CPU/GPU target",
            "next_gate": "Verify each material claim in developer source for exact build; collect matched measurement separately"}
    value = {"scope": "semantic review of all 92 batch-01 rows; not 92 verified game implementations",
             "source_ledger": "docs/research/CONTINUATION-2026-09-09.md",
             "counts": dict(Counter(r["research_review_2026_09_09"]["semantic_class"] for r in rows)), "rows": rows}
    with (ROOT / "validation/research/batch-01-review-2026-09-09.json").open("x", encoding="utf-8") as output:
        json.dump(value, output, ensure_ascii=False, indent=2)
    print(json.dumps({"rows": len(rows), "numeric_eligible": 0, "counts": value["counts"]}))

if __name__ == "__main__":
    main()
